// Younblock Android shell — Gradle settings (docs/android-port 04 §3,
// roadmap M3 task 6). One app module; the engine arrives as a
// gomobile-built AAR (android/app/libs/younblock.aar, regenerated by
// build-android.sh — never committed).
pluginManagement {
    repositories {
        google()
        mavenCentral()
        gradlePluginPortal()
    }
}
dependencyResolutionManagement {
    repositories {
        google()
        mavenCentral()
    }
}

rootProject.name = "younblock-android"
include(":app")
